http {
  server {                                   # /etc/nginx/sites-enabled/sklep
    listen 80 default_server; listen [::]:80 default_server;
    server_name sklep.lab.local sklep.firma.example;
    location = /favicon.ico { root /var/www/sklep; }          # dokladne
    location ^~ /assets/    { alias /var/www/sklep/; expires 7d; }  # prefiks, bez regex
    location ~* \.(env|git|bak)$ { return 404; }               # wyrazenie
    location /              { proxy_pass http://127.0.0.1:8080; }   # reszta -> aplikacja
  }
  server {                                   # /etc/nginx/sites-enabled/pomoc
    listen 80; server_name pomoc.lab.local;
    root /var/www/pomoc; index index.html;
    location / { try_files $uri $uri/ =404; }
  }
}
GET /assets/app.3f9c.js  Host: sklep.lab.local -> ^~ /assets/ -> /var/www/sklep/app.3f9c.js  (Nginx sam)
GET /api/produkty        Host: sklep.lab.local -> location /  -> proxy -> sklep (Spring Boot)
GET /faq.html            Host: pomoc.lab.local -> /var/www/pomoc/faq.html

